package com.example.web;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.stream.Collectors;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/files")
public class FileController {
    private final Path uploads = Paths.get("/srv/uploads");

    @GetMapping("/list")
    public List<String> list() throws IOException {
        return Files.list(uploads).map(p -> p.getFileName().toString()).collect(Collectors.toList());
    }

    @GetMapping("/download")
    public ResponseEntity<byte[]> download(@RequestParam("name") String name) throws IOException {
        byte[] body = Files.readAllBytes(uploads.resolve(name));
        return ResponseEntity.ok(body);
    }
}
